def set_quota(state, key, tokens) do
  if not is_number(tokens), do: raise("quota must be a number")
  used = usage(state, key)
  if used > tokens, do: raise("key #{key} has already used #{used} tokens, above quota #{tokens}")
  quotas = Map.get(state, "quotas", %{})
  {tokens, Map.put(state, "quotas", Map.put(quotas, key, tokens))}
end

